import 'dart:async';
import 'dart:io' show Platform;
import 'dart:math' as math;

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';

/// Fire-and-forget sound effects.
///
/// Call [init] once at start-up. Until it has finished, and whenever [enabled]
/// is false, every play method is a silent no-op. Nothing here ever throws:
/// on a device without audio, or with a sound file missing, that sound is
/// just skipped.
///
/// The files live in `assets/sounds/` and are generated by
/// `dart run tool/gen_sounds.dart`.
class Sfx {
  Sfx._();

  /// Master switch, toggled by settings.
  static bool enabled = true;

  /// Plops closer together than this are dropped, so a burst of swallowed
  /// items reads as a lively patter rather than a wall of noise.
  static const _plopGapMs = 45;

  // Each sound gets a few preloaded players ("voices") so quick repeats
  // overlap instead of cutting each other off.
  static final _plops = [
    _Sound('plop_1', voices: 3, volume: 0.85),
    _Sound('plop_2', voices: 3, volume: 0.85),
    _Sound('plop_3', voices: 3, volume: 0.85),
  ];
  static final _grow = _Sound('grow', voices: 2, volume: 0.9);
  static final _goal = _Sound('goal', voices: 2, volume: 0.9);
  static final _win = _Sound('win');
  static final _lose = _Sound('lose', volume: 0.9);
  static final _tick = _Sound('tick', voices: 2, volume: 0.8);
  static final _click = _Sound('click', voices: 2, volume: 0.8, minGapMs: 30);
  static final _coin = _Sound('coin', voices: 3, volume: 0.8, minGapMs: 50);

  static List<_Sound> get _all => [
    ..._plops,
    _grow,
    _goal,
    _win,
    _lose,
    _tick,
    _click,
    _coin,
  ];

  static final _clock = Stopwatch()..start();
  static final _random = math.Random();
  static Future<void>? _initializing;
  static bool _ready = false;
  static List<_Sound> _loadedPlops = const [];
  static int _lastPlopMs = -1 << 30;
  static int _lastPlop = -1;

  /// Preloads every sound. Safe to call more than once; never throws.
  static Future<void> init() => _initializing ??= _init();

  static Future<void> _init() async {
    // Under `flutter test` there are no platform plugins, and even creating
    // an AudioPlayer reports an error that fails the test. Stay silent.
    if (_isFlutterTest) return;
    try {
      // Effects mix with whatever the user is listening to instead of
      // stopping it. iOS: the ambient category (mixes with other audio,
      // follows the silent switch). Android: no audio focus request.
      await AudioPlayer.global.setAudioContext(
        AudioContext(
          iOS: AudioContextIOS(category: AVAudioSessionCategory.ambient),
          android: const AudioContextAndroid(
            contentType: AndroidContentType.sonification,
            usageType: AndroidUsageType.game,
            audioFocus: AndroidAudioFocus.none,
          ),
        ),
      );
    } catch (e) {
      debugPrint('Sfx: could not set the audio context ($e)');
    }
    try {
      await Future.wait([for (final sound in _all) sound.load()]);
    } catch (e) {
      debugPrint('Sfx: $e');
    }
    _loadedPlops = _plops.where((s) => s.isLoaded).toList();
    _ready = true;
  }

  static bool get _isFlutterTest {
    if (kIsWeb) return false;
    try {
      return Platform.environment.containsKey('FLUTTER_TEST');
    } catch (_) {
      return false;
    }
  }

  static bool get _canPlay => enabled && _ready;

  static int get _now => _clock.elapsedMilliseconds;

  /// An item dropping into the hole. Picks one of three plops (never the same
  /// one twice in a row) at a slightly random volume. Rate-limited, so it is
  /// fine to call for every item swallowed.
  static void plop() {
    if (!_canPlay || _loadedPlops.isEmpty) return;
    final now = _now;
    if (now - _lastPlopMs < _plopGapMs) return;
    _lastPlopMs = now;
    final count = _loadedPlops.length;
    var i = _random.nextInt(count);
    if (i == _lastPlop && count > 1) {
      i = (i + 1 + _random.nextInt(count - 1)) % count;
    }
    _lastPlop = i;
    _loadedPlops[i].play(now, gain: 0.8 + 0.2 * _random.nextDouble());
  }

  /// The hole grew a size.
  static void grow() => _play(_grow);

  /// One goal type fully collected.
  static void goal() => _play(_goal);

  /// Level complete.
  static void win() => _play(_win);

  /// Time's up.
  static void lose() => _play(_lose);

  /// Countdown tick (last seconds of the timer).
  static void tick() => _play(_tick);

  /// UI button tap.
  static void click() => _play(_click);

  /// Coins earned.
  static void coin() => _play(_coin);

  static void _play(_Sound sound) {
    if (_canPlay) sound.play(_now);
  }
}

/// One sound file with a fixed ring of preloaded players.
class _Sound {
  _Sound(this.name, {this.voices = 1, this.volume = 1, this.minGapMs = 0});

  final String name;
  final int voices;
  final double volume;

  /// Repeats closer together than this are dropped.
  final int minGapMs;

  final List<AudioPlayer> _players = [];
  int _next = 0;
  int _lastMs = -1 << 30;

  bool get isLoaded => _players.isNotEmpty;

  Future<void> load() async {
    final created = <AudioPlayer>[];
    try {
      for (var i = 0; i < voices; i++) {
        final player = AudioPlayer();
        created.add(player);
        await player.setReleaseMode(ReleaseMode.stop);
        await player.setPlayerMode(PlayerMode.lowLatency);
        await player.setSource(AssetSource('sounds/$name.wav'));
      }
      _players.addAll(created);
    } catch (e) {
      debugPrint('Sfx: could not load $name ($e)');
      for (final player in created) {
        unawaited(_quietly(player.dispose));
      }
    }
  }

  void play(int nowMs, {double gain = 1}) {
    if (_players.isEmpty || nowMs - _lastMs < minGapMs) return;
    _lastMs = nowMs;
    final player = _players[_next];
    _next = (_next + 1) % _players.length;
    unawaited(_quietly(() => _restart(player, volume * gain)));
  }

  /// Plays [player] from the start. The stop() matters: in low-latency mode
  /// (Android SoundPool) a player never reports completion, so without it a
  /// second resume() would be ignored.
  static Future<void> _restart(AudioPlayer player, double volume) async {
    await player.stop();
    if (player.volume != volume) await player.setVolume(volume);
    await player.resume();
  }

  static Future<void> _quietly(Future<void> Function() action) async {
    try {
      await action();
    } catch (e) {
      debugPrint('Sfx: $e');
    }
  }
}
